#!/bin/bash
# Удаляет .desktop-ярлыки в /home/shared/Desktop, если программа из Exec= не найдена.
# Файлы без строки Exec= не трогаются.

DIR="/home/shared/Desktop"

python3 - "$DIR" <<'EOF'
import os, re, shlex, shutil, sys

target = sys.argv[1]

def program_exists(cmd):
    if os.path.isabs(cmd):
        return os.path.isfile(cmd) and os.access(cmd, os.X_OK)
    return shutil.which(cmd) is not None

def get_program(exec_line):
    try:
        tokens = shlex.split(exec_line)
    except ValueError:
        return None
    # Пропускаем префиксы вида VAR=value и команду env
    i = 0
    while i < len(tokens):
        t = tokens[i]
        if re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', t) or t == 'env':
            i += 1
            continue
        break
    if i >= len(tokens):
        return None
    return tokens[i]

if not os.path.isdir(target):
    print(f"Каталог не найден: {target}")
    sys.exit(1)

for name in sorted(os.listdir(target)):
    if not name.endswith('.desktop'):
        continue
    path = os.path.join(target, name)
    if not os.path.isfile(path):
        continue

    exec_line = None
    in_entry = False
    try:
        with open(path, encoding='utf-8', errors='replace') as f:
            for line in f:
                s = line.strip()
                if s.startswith('['):
                    in_entry = (s == '[Desktop Entry]')
                    continue
                if in_entry and s.startswith('Exec=') and exec_line is None:
                    exec_line = s[len('Exec='):]
    except OSError as e:
        print(f"Пропуск {name}: {e}")
        continue

    if exec_line is None:
        print(f"Пропуск {name}: нет строки Exec=")
        continue

    prog = get_program(exec_line)
    if prog is None:
        print(f"Пропуск {name}: не удалось определить программу из Exec=")
        continue

    if program_exists(prog):
        print(f"OK      {name} -> {prog}")
    else:
        try:
            os.remove(path)
            print(f"УДАЛЁН  {name} -> {prog} не найден")
        except OSError as e:
            print(f"Ошибка удаления {name}: {e}")
EOF

