    *.pdf|*.doc|*.docx|*.odt|*.txt|*.xls|*.xlsx|*.ods|*.ppt|*.pptx|*.md) dir=Documents ;;
    *.png|*.jpg|*.jpeg|*.gif|*.svg|*.webp|*.bmp) dir=Images ;;
    *.zip|*.tar|*.gz|*.tgz|*.bz2|*.xz|*.7z|*.rar) dir=Archives ;;
    *.deb|*.rpm|*.appimage|*.sh|*.run|*.exe|*.msi) dir=Installers ;;
    *) dir=Other ;;
  esac
  mv -n -- "$f" "$dir/"
done
find . -maxdepth 1 -type l -exec mv -n -- {} Other/ \;
echo "=== Содержимое после очистки ==="
